          </section>
          <div class="registered-team" aria-label="Équipe à inscrire"><div v-for="pokemon in team" :key="pokemon.uuid"><img :src="sprite(pokemon)" alt=""><b>{{ pokemon.name || pokemon.truename }}</b><span>Niv. {{ pokemon.level }}</span></div></div>
